drawBorders() {
  const { left, top, width, height } = this.getAbsoluteLayout();

  const {
    borderTopWidth = 0,
    borderRightWidth = 0,
    borderBottomWidth = 0,
    borderLeftWidth = 0,
  } = this;

  const {
    borderTopLeftRadius = 0,
    borderTopRightRadius = 0,
    borderBottomRightRadius = 0,
    borderBottomLeftRadius = 0,
    borderTopColor = 'black',
    borderRightColor = 'black',
    borderBottomColor = 'black',
    borderLeftColor = 'black',
    borderTopStyle = 'solid',
    borderRightStyle = 'solid',
    borderBottomStyle = 'solid',
    borderLeftStyle = 'solid',
  } = this.getComputedStyles();

  this.root.instance.save();

  // Special case: All four radii are equal and widths are equal = rounded (circle/ellipse)
  const radii = [borderTopLeftRadius, borderTopRightRadius, borderBottomRightRadius, borderBottomLeftRadius];
  const allRadiiEqual = radii.every(r => r === radii[0]);
  const allWidthsEqual = borderTopWidth === borderRightWidth && borderTopWidth === borderBottomWidth && borderTopWidth === borderLeftWidth;
  const isRounded = allRadiiEqual && allWidthsEqual && borderTopWidth > 0 && borderTopLeftRadius > 0 && width === height;
  if (isRounded && borderTopWidth > 0) {
    // Draw a circle border with native PDF roundedRect stroke
    // Fill must be done in drawBackgroundColor
    this.root.instance
      .lineWidth(borderTopWidth)
      .strokeColor(borderTopColor)
      .roundedRect(left, top, width, height, borderTopLeftRadius)
      .stroke();
    this.root.instance.restore();
    return;
  }

  // Fallback: legacy segmented path
  // border top
  this.drawHorizontalBorder(
    [
      left + (borderTopLeftRadius > 0 ? borderTopWidth / 2 : 0),
      top + borderTopWidth / 2,
    ],
    [
      left + width - (borderTopRightRadius > 0 ? borderTopWidth / 2 : 0),
      top + borderTopWidth / 2,
    ],
    borderTopLeftRadius,
    borderTopRightRadius,
    borderTopWidth,
    borderTopColor,
    borderTopStyle,
  );

  // border right
  this.drawVerticalBorder(
    [
      left + width - borderRightWidth / 2,
      top + (borderTopRightRadius > 0 ? borderRightWidth / 2 : 0),
    ],
    [
      left + width - borderRightWidth / 2,
      top + height - (borderBottomRightRadius > 0 ? borderRightWidth / 2 : 0),
    ],
    -borderTopRightRadius,
    -borderBottomRightRadius,
    borderRightWidth,
    borderRightColor,
    borderRightStyle,
  );

  // border bottom
  this.drawHorizontalBorder(
    [
      left +
        width -
        (borderBottomRightRadius > 0 ? borderBottomWidth / 2 : 0),
      top + height - borderBottomWidth / 2,
    ],
    [
      left + (borderBottomLeftRadius > 0 ? borderBottomWidth / 2 : 0),
      top + height - borderBottomWidth / 2,
    ],
    -borderBottomRightRadius,
    -borderBottomLeftRadius,
    borderBottomWidth,
    borderBottomColor,
    borderBottomStyle,
  );

  // border left
  this.drawVerticalBorder(
    [
      left + borderLeftWidth / 2,
      top + height - (borderBottomLeftRadius > 0 ? borderLeftWidth / 2 : 0),
    ],
    [
      left + borderLeftWidth / 2,
      top + (borderTopLeftRadius > 0 ? borderLeftWidth / 2 : 0),
    ],
    borderBottomLeftRadius,
    borderTopLeftRadius,
    borderLeftWidth,
    borderLeftColor,
    borderLeftStyle,
  );

  this.root.instance.restore();
},

